    const drawPicks = () => { picks.innerHTML = list().map(p => `<button data-m="${p.mint}"><img src="${esc(p.img || '/coins/1.png')}" alt="">${esc(p.sym)}</button>`).join(''); labels(); }; el._picks = drawPicks; drawPicks();
